:root {
  --primary: #1f6feb;
  --primary-dark: #1558c0;
  --accent: #e5484d;
  --text: #1f2328;
  --muted: #6b7280;
  --border: #e5e7eb;
  --bg: #f7f7f8;
  --card: #fff;
  --radius: 12px;
  --shadow: 0 1px 3px rgba(0, 0, 0, 0.06), 0 4px 16px rgba(0, 0, 0, 0.04);
}

* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: "Hiragino Sans", "Noto Sans JP", "Yu Gothic", system-ui, sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
}
a { color: inherit; text-decoration: none; }
a:hover { color: var(--primary); }
img { max-width: 100%; }
h1, h2, h3 { line-height: 1.3; }
button { font: inherit; cursor: pointer; }
input, select { font: inherit; }
[hidden] { display: none !important; }

.container { max-width: 1200px; margin: 0 auto; padding: 0 20px; }
.main { min-height: 60vh; padding-top: 24px; padding-bottom: 60px; outline: none; }
.muted { color: var(--muted); }
.small { font-size: 0.85rem; }
.right { text-align: right; }
.warn { color: var(--accent); }

/* ---------- Header ---------- */
.header { background: #fff; border-bottom: 1px solid var(--border); position: sticky; top: 0; z-index: 50; }
.header__inner { display: flex; align-items: center; gap: 24px; height: 64px; }
.logo { font-size: 1.4rem; font-weight: 800; letter-spacing: -0.02em; white-space: nowrap; }
.logo span { color: var(--primary); }
.search { flex: 1; display: flex; max-width: 520px; }
.search input {
  flex: 1; padding: 9px 14px; border: 1px solid var(--border); border-right: 0;
  border-radius: 999px 0 0 999px; background: var(--bg); outline: none;
}
.search input:focus { border-color: var(--primary); background: #fff; }
.search button { padding: 0 16px; border: 1px solid var(--primary); background: var(--primary); color: #fff; border-radius: 0 999px 999px 0; }
.header__nav { display: flex; gap: 18px; margin-left: auto; }
.nav-link { display: flex; align-items: center; gap: 4px; font-weight: 600; white-space: nowrap; }
.badge {
  min-width: 20px; height: 20px; padding: 0 6px; border-radius: 999px; background: var(--accent);
  color: #fff; font-size: 0.75rem; display: inline-flex; align-items: center; justify-content: center;
}
.category-bar { border-top: 1px solid var(--border); }
.category-bar .container { display: flex; gap: 4px; overflow-x: auto; padding-top: 6px; padding-bottom: 6px; }
.cat-link { padding: 6px 14px; border-radius: 999px; font-size: 0.9rem; white-space: nowrap; color: var(--muted); }
.cat-link:hover { background: var(--bg); }
.cat-link.active { background: var(--text); color: #fff; }

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  padding: 9px 18px; border-radius: 8px; border: 1px solid transparent; font-weight: 600;
  transition: background 0.15s, border-color 0.15s, transform 0.05s; text-align: center;
}
.btn:active:not(:disabled) { transform: translateY(1px); }
.btn:disabled { opacity: 0.5; cursor: not-allowed; }
.btn--primary { background: var(--primary); color: #fff; }
.btn--primary:hover:not(:disabled) { background: var(--primary-dark); color: #fff; }
.btn--outline { background: #fff; border-color: var(--border); }
.btn--outline:hover { border-color: var(--primary); color: var(--primary); }
.btn--outline.active { color: var(--accent); border-color: var(--accent); }
.btn--ghost { background: transparent; color: var(--muted); }
.btn--light { background: #fff; color: var(--primary); }
.btn--light:hover { background: #eef4ff; }
.btn--block { width: 100%; }
.btn--lg { padding: 12px 22px; font-size: 1rem; }
.link-btn { background: none; border: 0; color: var(--muted); text-decoration: underline; padding: 0; font-size: 0.85rem; }
.link-btn:hover { color: var(--accent); }

/* ---------- Hero ---------- */
.hero {
  display: flex; align-items: center; justify-content: space-between; gap: 20px;
  padding: 40px 48px; border-radius: 20px; color: #fff;
  background: linear-gradient(120deg, #1f6feb, #7c3aed);
}
.hero h1 { font-size: 2.2rem; margin: 8px 0 12px; }
.hero p { margin: 0 0 20px; opacity: 0.95; }
.hero code { background: rgba(255, 255, 255, 0.2); padding: 2px 8px; border-radius: 6px; }
.hero__sub { font-weight: 700; letter-spacing: 0.1em; font-size: 0.85rem; margin: 0 !important; }
.hero__emoji { font-size: 7rem; line-height: 1; }
.features { list-style: none; padding: 0; margin: 20px 0 32px; display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.features li { background: #fff; border-radius: var(--radius); padding: 14px; text-align: center; box-shadow: var(--shadow); font-size: 0.9rem; }

/* ---------- Shop layout ---------- */
.shop { display: grid; grid-template-columns: 220px 1fr; gap: 28px; align-items: start; }
.filters { background: #fff; border-radius: var(--radius); padding: 18px; box-shadow: var(--shadow); position: sticky; top: 130px; }
.filters h2 { font-size: 1rem; margin: 0 0 12px; }
.field { display: flex; flex-direction: column; gap: 4px; margin-bottom: 14px; font-size: 0.9rem; }
.field > span { font-weight: 600; }
.field em { color: var(--accent); font-style: normal; }
.field input, .field select {
  padding: 9px 12px; border: 1px solid var(--border); border-radius: 8px; background: #fff; outline: none;
}
.field input:focus, .field select:focus { border-color: var(--primary); box-shadow: 0 0 0 3px rgba(31, 111, 235, 0.15); }
.field.invalid input { border-color: var(--accent); background: #fff5f5; }
.field.invalid > span::after { content: " — 正しく入力してください"; color: var(--accent); font-weight: 400; font-size: 0.8rem; }
.check { display: flex; align-items: center; gap: 8px; font-size: 0.9rem; cursor: pointer; }
.products__head { display: flex; align-items: baseline; gap: 12px; margin-bottom: 16px; }
.products__head h2 { margin: 0; font-size: 1.3rem; }

/* ---------- Product card ---------- */
.grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap: 18px; }
.card { position: relative; background: var(--card); border-radius: var(--radius); overflow: hidden; box-shadow: var(--shadow); display: flex; flex-direction: column; transition: transform 0.15s, box-shadow 0.15s; }
.card:hover { transform: translateY(-3px); box-shadow: 0 8px 24px rgba(0, 0, 0, 0.08); }
.card__img { position: relative; aspect-ratio: 1 / 1; display: flex; align-items: center; justify-content: center; }
.card__emoji { font-size: 5rem; transition: transform 0.2s; }
.card:hover .card__emoji { transform: scale(1.08); }
.card__tags { position: absolute; top: 10px; left: 10px; display: flex; gap: 4px; }
.tag { font-size: 0.7rem; font-weight: 700; padding: 2px 8px; border-radius: 4px; color: #fff; }
.tag--sale { background: var(--accent); }
.tag--new { background: #10b981; }
.tag--popular { background: #f59e0b; }
.soldout { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(255, 255, 255, 0.65); font-weight: 800; letter-spacing: 0.1em; color: var(--muted); }
.fav-btn {
  position: absolute; top: 8px; right: 8px; width: 36px; height: 36px; border-radius: 50%;
  border: 0; background: #fff; box-shadow: var(--shadow); font-size: 1.1rem; color: var(--muted);
}
.fav-btn.active, .fav-btn:hover { color: var(--accent); }
.card__body { padding: 12px 14px 14px; display: flex; flex-direction: column; gap: 4px; flex: 1; }
.card__body .btn { margin-top: auto; }
.card__cat { margin: 0; font-size: 0.75rem; color: var(--muted); }
.card__name { margin: 0; font-size: 0.95rem; font-weight: 600; }
.card__rating { font-size: 0.85rem; }
.stars { color: #f59e0b; letter-spacing: 1px; }
.price { display: flex; align-items: baseline; gap: 8px; font-weight: 700; font-size: 1.1rem; margin-bottom: 8px; }
.price__old { color: var(--muted); text-decoration: line-through; font-weight: 400; font-size: 0.85rem; }
.price__sale { color: var(--accent); }
.price--lg { font-size: 1.8rem; margin: 12px 0; }
.price--lg .price__old { font-size: 1rem; }
.off { background: var(--accent); color: #fff; font-size: 0.8rem; padding: 2px 8px; border-radius: 4px; }

/* ---------- Detail ---------- */
.breadcrumb { font-size: 0.85rem; color: var(--muted); margin-bottom: 16px; }
.detail { display: grid; grid-template-columns: 1fr 1fr; gap: 40px; background: #fff; padding: 28px; border-radius: 20px; box-shadow: var(--shadow); }
.detail__img { aspect-ratio: 1 / 1; border-radius: 16px; display: flex; align-items: center; justify-content: center; font-size: 10rem; }
.detail__info h1 { margin: 4px 0 8px; font-size: 1.7rem; }
.detail__desc { color: #374151; }
.stock { font-weight: 700; color: #10b981; }
.stock--low { color: #f59e0b; }
.stock--out { color: var(--muted); }
.sizes { border: 0; padding: 0; margin: 0 0 16px; display: flex; gap: 8px; flex-wrap: wrap; }
.sizes legend { font-weight: 600; margin-bottom: 6px; font-size: 0.9rem; }
.sizes input { position: absolute; opacity: 0; }
.sizes span { display: inline-block; min-width: 52px; text-align: center; padding: 8px 12px; border: 1px solid var(--border); border-radius: 8px; cursor: pointer; }
.sizes input:checked + span { border-color: var(--primary); background: #eef4ff; color: var(--primary); font-weight: 700; }
.sizes input:focus-visible + span { outline: 2px solid var(--primary); }
.add-form__row { display: flex; gap: 10px; align-items: flex-end; flex-wrap: wrap; }
.qty { display: flex; flex-direction: column; font-size: 0.9rem; font-weight: 600; }
.qty input { width: 80px; padding: 11px; border: 1px solid var(--border); border-radius: 8px; }
.detail__notes { list-style: none; padding: 16px; margin: 20px 0 0; background: var(--bg); border-radius: 10px; font-size: 0.9rem; }
.related { margin-top: 40px; }

/* ---------- Cart ---------- */
.page-title { font-size: 1.6rem; margin: 0 0 20px; }
.cart, .checkout { display: grid; grid-template-columns: 1fr 360px; gap: 28px; align-items: start; }
.cart__list { list-style: none; padding: 0; margin: 0; background: #fff; border-radius: var(--radius); box-shadow: var(--shadow); }
.cart-item { display: grid; grid-template-columns: 80px 1fr auto 100px auto; gap: 16px; align-items: center; padding: 16px; border-bottom: 1px solid var(--border); }
.cart-item:last-child { border-bottom: 0; }
.cart-item__img { width: 80px; height: 80px; border-radius: 10px; display: flex; align-items: center; justify-content: center; font-size: 2.5rem; }
.cart-item__info p { margin: 2px 0; font-size: 0.9rem; }
.cart-item__name { font-weight: 600; }
.cart-item__total { font-weight: 700; text-align: right; margin: 0; }
.qty-control { display: flex; align-items: center; border: 1px solid var(--border); border-radius: 8px; overflow: hidden; }
.qty-control button { width: 34px; height: 34px; border: 0; background: var(--bg); }
.qty-control button:disabled { opacity: 0.4; cursor: not-allowed; }
.qty-control span { min-width: 36px; text-align: center; font-weight: 600; }
.summary { background: #fff; border-radius: var(--radius); padding: 20px; box-shadow: var(--shadow); position: sticky; top: 130px; display: flex; flex-direction: column; gap: 10px; }
.summary h2 { margin: 0; font-size: 1.1rem; }
.summary__table { width: 100%; border-collapse: collapse; margin: 6px 0; }
.summary__table th, .summary__table td { padding: 6px 0; font-weight: 400; }
.summary__table th { text-align: left; }
.summary__table td { text-align: right; }
.summary__total th, .summary__total td { border-top: 1px solid var(--border); padding-top: 12px; font-weight: 800; font-size: 1.2rem; }
.discount { color: var(--accent); }
.ship-note { margin: 0; padding: 10px 12px; background: #fff8e6; border-radius: 8px; font-size: 0.9rem; }
.ship-note--ok { background: #e8f8f0; }
.coupon { display: flex; gap: 8px; }
.coupon input { flex: 1; min-width: 0; padding: 9px 12px; border: 1px solid var(--border); border-radius: 8px; text-transform: uppercase; }
.summary .small { margin: 0; }

/* ---------- Checkout ---------- */
.steps { list-style: none; display: flex; gap: 0; padding: 0; margin: 0 0 24px; counter-reset: step; }
.steps li { flex: 1; text-align: center; position: relative; color: var(--muted); font-size: 0.85rem; counter-increment: step; }
.steps li::before {
  content: counter(step); display: flex; align-items: center; justify-content: center; margin: 0 auto 6px;
  width: 30px; height: 30px; border-radius: 50%; background: var(--border); color: var(--muted); font-weight: 700; position: relative; z-index: 1;
}
.steps li:not(:first-child)::after { content: ""; position: absolute; top: 15px; right: 50%; width: 100%; height: 2px; background: var(--border); }
.steps li.done::before { content: "✓"; background: #10b981; color: #fff; }
.steps li.done:not(:first-child)::after, .steps li.current:not(:first-child)::after { background: #10b981; }
.steps li.current { color: var(--text); font-weight: 700; }
.steps li.current::before { background: var(--primary); color: #fff; }
.panel { background: #fff; border-radius: var(--radius); padding: 22px; box-shadow: var(--shadow); margin-bottom: 20px; }
.panel h2 { margin: 0 0 16px; font-size: 1.1rem; }
.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 0 16px; }
.form-grid .full { grid-column: 1 / -1; }
.pay-options { display: flex; flex-direction: column; gap: 8px; margin-bottom: 16px; }
.pay-options label { padding: 12px 14px; border: 1px solid var(--border); border-radius: 8px; cursor: pointer; display: flex; gap: 8px; align-items: center; }
.pay-options label:has(input:checked) { border-color: var(--primary); background: #eef4ff; }
.mini-list { list-style: none; padding: 0; margin: 0; font-size: 0.9rem; }
.mini-list li { display: flex; justify-content: space-between; gap: 12px; padding: 6px 0; border-bottom: 1px dashed var(--border); }
.mini-list li span:last-child { white-space: nowrap; }

/* ---------- Complete / Orders ---------- */
.complete { text-align: center; background: #fff; border-radius: 20px; padding: 48px 24px; box-shadow: var(--shadow); max-width: 640px; margin: 0 auto; }
.complete__icon { font-size: 4rem; }
.complete h1 { margin: 8px 0 12px; }
.complete__box { text-align: left; background: var(--bg); padding: 16px 20px; border-radius: 10px; margin: 20px 0; }
.complete__box p { margin: 4px 0; }
.complete__actions { display: flex; gap: 12px; justify-content: center; }
.order { position: relative; }
.order__head { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; padding-bottom: 12px; margin-bottom: 8px; border-bottom: 1px solid var(--border); font-size: 0.9rem; }
.status { display: inline-block; margin-top: 12px; padding: 4px 12px; border-radius: 999px; background: #eef4ff; color: var(--primary); font-size: 0.8rem; font-weight: 700; }

/* ---------- Empty / Toast / Footer ---------- */
.empty { text-align: center; padding: 60px 20px; background: #fff; border-radius: var(--radius); box-shadow: var(--shadow); }
.empty__icon { font-size: 3.5rem; }
.empty p { color: var(--muted); }
.toast {
  position: fixed; left: 50%; bottom: 24px; transform: translate(-50%, 120px); background: var(--text); color: #fff;
  padding: 12px 22px; border-radius: 999px; box-shadow: 0 8px 24px rgba(0, 0, 0, 0.2); transition: transform 0.25s; z-index: 100; font-size: 0.9rem; max-width: 90vw;
}
.toast.show { transform: translate(-50%, 0); }
.footer { background: #111827; color: #d1d5db; padding: 40px 0 20px; font-size: 0.9rem; }
.footer__inner { display: grid; grid-template-columns: 2fr 1fr 1fr; gap: 24px; }
.footer ul { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 6px; }
.footer a:hover { color: #fff; }
.logo--footer { color: #fff; }
.footer__copy { text-align: center; color: #6b7280; margin: 30px 0 0; font-size: 0.8rem; }

/* ---------- Responsive ---------- */
@media (max-width: 900px) {
  .shop, .cart, .checkout, .detail { grid-template-columns: 1fr; }
  .filters, .summary { position: static; }
  .filters form { display: grid; grid-template-columns: 1fr 1fr; gap: 0 12px; align-items: end; }
  .hero { padding: 28px; }
  .hero__emoji { display: none; }
}
@media (max-width: 640px) {
  .header__inner { flex-wrap: wrap; height: auto; padding-top: 10px; padding-bottom: 10px; gap: 10px; }
  .search { order: 3; max-width: none; flex-basis: 100%; }
  .nav-link { font-size: 0.85rem; }
  .hero h1 { font-size: 1.6rem; }
  .features { grid-template-columns: 1fr; }
  .grid { grid-template-columns: repeat(2, 1fr); gap: 12px; }
  .card__emoji { font-size: 3.5rem; }
  .cart-item { grid-template-columns: 64px 1fr auto; }
  .cart-item__img { width: 64px; height: 64px; }
  .cart-item__total { grid-column: 2; text-align: left; }
  .form-grid, .order__head { grid-template-columns: 1fr 1fr; }
  .footer__inner { grid-template-columns: 1fr; }
  .detail { padding: 16px; }
  .detail__img { font-size: 6rem; }
}

