"use strict";

/* ========== ユーティリティ ========== */
const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => [...root.querySelectorAll(sel)];
const yen = (n) => "¥" + Math.round(n).toLocaleString("ja-JP");
const esc = (s) =>
  String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const findProduct = (id) => PRODUCTS.find((p) => p.id === Number(id));
const priceOf = (p) => p.salePrice ?? p.price;
const categoryName = (id) => (CATEGORIES.find((c) => c.id === id) || {}).name || "";

const store = {
  get(key, fallback) {
    try {
      return JSON.parse(localStorage.getItem("mm_" + key)) ?? fallback;
    } catch {
      return fallback;
    }
  },
  set(key, value) {
    localStorage.setItem("mm_" + key, JSON.stringify(value));
  },
};

let toastTimer;
function toast(msg) {
  const el = $("#toast");
  el.textContent = msg;
  el.classList.add("show");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => el.classList.remove("show"), 2200);
}

function stars(rating) {
  const full = Math.round(rating);
  return `<span class="stars" aria-label="評価 ${rating}">${"★".repeat(full)}${"☆".repeat(5 - full)}</span>`;
}

/* ========== 状態管理（カート / お気に入り / 注文） ========== */
const state = {
  cart: store.get("cart", []), // [{ id, qty, size }]
  favorites: store.get("favorites", []), // [id]
  orders: store.get("orders", []),
  coupon: store.get("coupon", null),
};
// 存在しない商品・不正なクーポンを除外
state.cart = state.cart.filter((l) => findProduct(l.id));
if (state.coupon && !COUPONS[state.coupon]) state.coupon = null;

function save() {
  store.set("cart", state.cart);
  store.set("favorites", state.favorites);
  store.set("orders", state.orders);
  store.set("coupon", state.coupon);
  updateBadges();
}

function updateBadges() {
  $("#cartCount").textContent = state.cart.reduce((s, i) => s + i.qty, 0);
  $("#favCount").textContent = state.favorites.length;
}

function addToCart(id, qty = 1, size = null) {
  const p = findProduct(id);
  if (!p || p.stock === 0) return;
  const line = state.cart.find((i) => i.id === p.id && i.size === size);
  const current = line ? line.qty : 0;
  const next = Math.min(current + qty, p.stock);
  if (next === current) {
    toast("在庫数の上限です");
    return;
  }
  if (line) line.qty = next;
  else state.cart.push({ id: p.id, qty: next, size });
  save();
  toast(`「${p.name}」をカートに追加しました`);
}

function setQty(index, qty) {
  const line = state.cart[index];
  if (!line) return;
  const p = findProduct(line.id);
  if (qty <= 0) state.cart.splice(index, 1);
  else line.qty = Math.min(qty, p.stock);
  save();
}

function toggleFavorite(id) {
  id = Number(id);
  const i = state.favorites.indexOf(id);
  if (i >= 0) {
    state.favorites.splice(i, 1);
    toast("お気に入りから削除しました");
  } else {
    state.favorites.push(id);
    toast("お気に入りに追加しました");
  }
  save();
}

function calcTotals() {
  const subtotal = state.cart.reduce((s, i) => s + priceOf(findProduct(i.id)) * i.qty, 0);
  let discount = 0;
  const c = state.coupon && COUPONS[state.coupon];
  if (c) {
    if (c.min && subtotal < c.min) discount = 0;
    else discount = c.type === "percent" ? Math.floor((subtotal * c.value) / 100) : c.value;
  }
  discount = Math.min(discount, subtotal);
  const afterDiscount = subtotal - discount;
  const shipping = subtotal === 0 || afterDiscount >= FREE_SHIPPING_THRESHOLD ? 0 : SHIPPING_FEE;
  const total = afterDiscount + shipping;
  const tax = Math.floor(total - total / (1 + TAX_RATE));
  return { subtotal, discount, shipping, total, tax };
}

/* ========== 共通パーツ ========== */
function productCard(p) {
  const fav = state.favorites.includes(p.id);
  const soldOut = p.stock === 0;
  const tagLabels = { sale: "SALE", new: "NEW", popular: "人気" };
  return `
    <article class="card">
      <a href="#/product/${p.id}" class="card__img" style="background:${p.color}">
        <span class="card__emoji">${p.emoji}</span>
        <div class="card__tags">${p.tags.map((t) => `<span class="tag tag--${t}">${tagLabels[t]}</span>`).join("")}</div>
        ${soldOut ? '<span class="soldout">SOLD OUT</span>' : ""}
      </a>
      <button class="fav-btn ${fav ? "active" : ""}" data-fav="${p.id}" aria-label="お気に入り">${fav ? "♥" : "♡"}</button>
      <div class="card__body">
        <p class="card__cat">${categoryName(p.category)}</p>
        <h3 class="card__name"><a href="#/product/${p.id}">${esc(p.name)}</a></h3>
        <div class="card__rating">${stars(p.rating)} <small>(${p.reviews})</small></div>
        <div class="price">
