const COD_FEE = 330;

function afterCheckout() {
  const form = $("#checkoutForm");
  if (!form) return;
  const cardFields = $("#cardFields");
  const isCard = () => form.payment.value === "card";
  const refresh = () => {
    cardFields.hidden = !isCard();
    $$("input", cardFields).forEach((i) => (i.required = isCard()));
    const t = calcTotals();
    if (form.payment.value === "cod") {
      t.total += COD_FEE;
      t.tax = Math.floor(t.total - t.total / (1 + TAX_RATE));
    }
    $("#summaryBox").innerHTML =
      summaryTable(t).replace("<tr class=\"summary__total\">", form.payment.value === "cod" ? `<tr><th>代引手数料</th><td>${yen(COD_FEE)}</td></tr><tr class="summary__total">` : "<tr class=\"summary__total\">");
  };
  form.addEventListener("change", (e) => e.target.name === "payment" && refresh());
  refresh();

  form.addEventListener("submit", (e) => {
    e.preventDefault();
    $$(".field.invalid", form).forEach((f) => f.classList.remove("invalid"));
    let ok = true;
    $$("input[required]", form).forEach((input) => {
      let valid = input.checkValidity() && input.value.trim() !== "";
      if (input.name === "card") valid = /^\d{14,16}$/.test(input.value.replace(/\s|-/g, ""));
      if (input.name === "exp") valid = /^(0[1-9]|1[0-2])\/\d{2}$/.test(input.value.trim());
      if (input.name === "cvc") valid = /^\d{3,4}$/.test(input.value.trim());
      if (!valid) {
        ok = false;
        input.closest(".field").classList.add("invalid");
      }
    });
    if (!ok) {
      toast("入力内容をご確認ください");
      $(".field.invalid input", form)?.focus();
      return;
    }

    const fd = Object.fromEntries(new FormData(form));
    const address = { name: fd.name, tel: fd.tel, email: fd.email, zip: fd.zip, pref: fd.pref, address: fd.address };
    if (fd.remember) store.set("address", address);
    else localStorage.removeItem("mm_address");

    const t = calcTotals();
    const codFee = fd.payment === "cod" ? COD_FEE : 0;
    const order = {
      id: "MM" + Date.now().toString().slice(-8),
      date: new Date().toISOString(),
      items: state.cart.map((l) => {
        const p = findProduct(l.id);
        return { id: p.id, name: p.name, emoji: p.emoji, size: l.size, qty: l.qty, price: priceOf(p) };
      }),
      ...t,
      codFee,
      total: t.total + codFee,
      payment: fd.payment,
      address,
    };
    // 在庫を減らす（デモ: メモリ上のみ）
    order.items.forEach((i) => (findProduct(i.id).stock -= i.qty));
    state.orders.unshift(order);
    state.cart = [];
    state.coupon = null;
    save();
    location.hash = "#/complete/" + order.id;
  });
}

