/* ========== ルーター ========== */
function parseHash() {
  const raw = location.hash.replace(/^#/, "") || "/";
  const [path, query = ""] = raw.split("?");
  return { parts: path.split("/").filter(Boolean), params: new URLSearchParams(query) };
}

function render() {
  const { parts, params } = parseHash();
  const app = $("#app");
  const [page, arg] = parts;
  let html, after;
  switch (page) {
    case undefined: html = pageHome(params); after = () => afterHome(params); break;
    case "product": html = pageProduct(arg); after = () => afterProduct(arg); break;
    case "cart": html = pageCart(); after = afterCart; break;
    case "checkout": html = pageCheckout(); after = afterCheckout; break;
    case "complete": html = pageComplete(arg); break;
    case "orders": html = pageOrders(); break;
    case "favorites": html = pageFavorites(); break;
    default: renderCategoryNav(null); html = emptyState("🚧", "ページが見つかりませんでした。", "トップへ戻る");
  }
  app.innerHTML = html;
  after?.();
  updateBadges();
}

/* ========== グローバルイベント ========== */
document.addEventListener("click", (e) => {
  const t = e.target.closest("[data-add],[data-fav],[data-inc],[data-dec],[data-remove]");
  if (!t) return;
  const d = t.dataset;
  if (d.add) {
    const p = findProduct(d.add);
    if (p.sizes) location.hash = "#/product/" + p.id; // サイズ選択が必要な商品は詳細へ
    else addToCart(d.add);
  } else if (d.fav) {
    toggleFavorite(d.fav);
    render();
  } else if (d.inc) {
    setQty(+d.inc, state.cart[+d.inc].qty + 1);
    render();
  } else if (d.dec) {
    setQty(+d.dec, state.cart[+d.dec].qty - 1);
    render();
  } else if (d.remove) {
    setQty(+d.remove, 0);
    toast("商品を削除しました");
    render();
  }
});

$("#searchForm").addEventListener("submit", (e) => {
  e.preventDefault();
  const q = $("#searchInput").value.trim();
  location.hash = q ? "#/?q=" + encodeURIComponent(q) : "#/";
});

let lastPath = null;
window.addEventListener("hashchange", () => {
  const path = location.hash.split("?")[0];
  render();
  if (path !== lastPath) window.scrollTo(0, 0);
  lastPath = path;
});

lastPath = location.hash.split("?")[0];
render();
